window.ShelfParts=window.ShelfParts||{};window.ShelfParts.addCoverImage=function addCoverImage(ed){"use strict";const INK=`#313D45`,PAPER=`#FAFAF7`;const BOOK_WIDE=1.1;Object.assign(ed,{drawBook,bookCanvas,BOOK_WIDE});const font=(weight,size)=>`${weight} ${size}px Figtree, system-ui, sans-serif`;function coverPath(x,W,H){const r=.035*W;x.beginPath();if(x.roundRect)x.roundRect(0,0,W,H,[0,r,r,0]);else x.rect(0,0,W,H)}function spaced(x,text,cx,y,em,size){const gap=em*size;if(`letterSpacing`in x)x.letterSpacing=`${gap}px`;else{x.fillText(text,cx,y);return}x.fillText(text,cx+gap/2,y);x.letterSpacing=`0px`}let grain;function grainImage(){if(!grain){const v=getComputedStyle(document.documentElement).getPropertyValue(`--grain`);const m=/url\(["']?(.*?)["']?\)\s*$/.exec(v.trim());grain=ed.loadImage(m?m[1]:``).then(img=>{if(!img)return null;const c=document.createElement(`canvas`);c.width=160;c.height=160;c.getContext(`2d`).drawImage(img,0,0,160,160);return c})}return grain}const markSrc=(b,partner,stop)=>`data:image/svg+xml;charset=utf-8,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="240" height="240">${b.mark.replace(/var\(--p\)/g,partner).replace(/var\(--s, #FFD100\)/g,stop)}</svg>`)}`;function drawEdge(x,b,colors,W,H){x.fillStyle=`#FFFFFF`;x.fillRect(W*.97,H*.012,W*.045,H*.976);x.fillStyle=`#E6E6E1`;for(let k=1;k<=3;k++)x.fillRect(W*(.995+k*.005),H*.012,Math.max(1,W*.0015),H*.976);for(const[label,top,h,w,,light]of b.tabs){const tx=W*.975,ty=H*top/100,tw=W*w,th=H*h/100,r=W*.03;x.beginPath();if(x.roundRect)x.roundRect(tx,ty,tw,th,[0,r,r,0]);else x.rect(tx,ty,tw,th);x.fillStyle=light?colors.light:INK;x.fill();x.save();x.translate(tx+tw/2+W*.006,ty+th/2);x.rotate(Math.PI/2);x.fillStyle=light?INK:PAPER;x.font=font(600,W*.04);x.textAlign=`center`;x.textBaseline=`middle`;spaced(x,label,0,0,.02,W*.04);x.restore()}}async function drawBook(x,i,W){const b=ed.BOOKS[i],c=ed.colorOf(b),colors=ed.COLORS[c];const partner=ed.partnerOf(b,c),stop=b.inks&&b.inks[c]&&b.inks[c].s||`#FFD100`;const H=W*1.36;if(document.fonts&&document.fonts.ready)await document.fonts.ready;const[mark,paper]=await Promise.all([ed.loadImage(markSrc(b,partner,stop)),grainImage()]);drawEdge(x,b,colors,W,H);x.save();coverPath(x,W,H);x.clip();x.fillStyle=colors.band;x.fillRect(0,0,W,H);if(paper){const p=x.createPattern(paper,`repeat`);if(p&&p.setTransform&&window.DOMMatrix)p.setTransform(new DOMMatrix().scale(W/ed.W));x.globalCompositeOperation=`overlay`;x.fillStyle=p;x.fillRect(0,0,W,H);x.globalCompositeOperation=`source-over`}x.fillStyle=`rgba(0, 0, 0, .08)`;x.fillRect(0,0,W*.029,H);if(mark)x.drawImage(mark,W*.3,H*.3,W*.4,W*.4);x.fillStyle=partner;x.font=font(700,W*.044);x.textAlign=`center`;x.textBaseline=`bottom`;spaced(x,b.short.toUpperCase(),W/2,H*.92,.18,W*.044);const St=window.DFStickers;for(const s of St?St.list(b.id):[])await ed.drawSticker(x,s,W,H);x.restore()}async function bookCanvas(i,W){const cv=document.createElement(`canvas`);cv.width=Math.ceil(W*BOOK_WIDE);cv.height=Math.ceil(W*1.36);await drawBook(cv.getContext(`2d`),i,W);return cv}};
;

