window.ShelfParts=window.ShelfParts||{};window.ShelfParts.addShelfImage=function addShelfImage(ed){"use strict";const SIZES={post:[1080,1350],story:[1080,1920],square:[1080,1080]};Object.assign(ed,{shelfImage,IMAGE_SIZES:SIZES});const INK=`#313D45`,PAPER=`#FAFAF7`,WORDS=`DOCUMENTING FICTIONS`;function wordmark(x,w,y,u){x.fillStyle=INK;x.font=`700 ${30*u}px Figtree, system-ui, sans-serif`;x.textAlign=`center`;x.textBaseline=`alphabetic`;if(!(`letterSpacing`in x)){x.fillText(WORDS,w/2,y);return}const gap=Math.max(0,(540*u-x.measureText(WORDS).width)/(WORDS.length-1));x.letterSpacing=`${gap}px`;x.fillText(WORDS,w/2+gap/2,y);x.letterSpacing=`0px`}function floorShadow(x,cx,cy,rw,alpha){x.save();x.translate(cx,cy);x.scale(1,.1);const g=x.createRadialGradient(0,0,0,0,0,rw);g.addColorStop(0,`rgba(49, 61, 69, ${alpha})`);g.addColorStop(1,`rgba(49, 61, 69, 0)`);x.fillStyle=g;x.beginPath();x.arc(0,0,rw,0,Math.PI*2);x.fill();x.restore()}function quadOf(i){const front=ed.slots[i].querySelector(`.front`);const pts=[[0,0],[ed.BOOK_WIDE,0],[ed.BOOK_WIDE,1],[0,1]].map(([u,v])=>{const p=document.createElement(`i`);p.style.cssText=`position:absolute;left:${u*100}%;top:${v*100}%;width:0;height:0`;front.append(p);const r=p.getBoundingClientRect();p.remove();return{x:r.left,y:r.top}});const fog=Number(ed.slots[i].querySelector(`.fog`).style.opacity)||0;return{i,z:Number(ed.slots[i].style.zIndex)||0,fog,pts}}function squareTo(p){const[a0,a1,a2,a3]=p;const dx1=a1.x-a2.x,dx2=a3.x-a2.x,dx3=a0.x-a1.x+a2.x-a3.x;const dy1=a1.y-a2.y,dy2=a3.y-a2.y,dy3=a0.y-a1.y+a2.y-a3.y;const den=dx1*dy2-dx2*dy1;const g=den?(dx3*dy2-dx2*dy3)/den:0,h=den?(dx1*dy3-dx3*dy1)/den:0;const A=a1.x-a0.x+g*a1.x,B=a3.x-a0.x+h*a3.x,D=a1.y-a0.y+g*a1.y,E=a3.y-a0.y+h*a3.y;return(u,v)=>{const q=g*u+h*v+1;return{x:(A*u+B*v+a0.x)/q,y:(D*u+E*v+a0.y)/q}}}function triangle(x,img,s,d){const[s0,s1,s2]=s,[d0,d1,d2]=d;const ux=s1.x-s0.x,uy=s1.y-s0.y,vx=s2.x-s0.x,vy=s2.y-s0.y,det=ux*vy-vx*uy;if(!det)return;const px=d1.x-d0.x,py=d1.y-d0.y,qx=d2.x-d0.x,qy=d2.y-d0.y;const a=(px*vy-qx*uy)/det,c=(qx*ux-px*vx)/det,b=(py*vy-qy*uy)/det,e=(qy*ux-py*vx)/det;const mx=(d0.x+d1.x+d2.x)/3,my=(d0.y+d1.y+d2.y)/3;const out=p=>{const l=Math.hypot(p.x-mx,p.y-my)||1;return{x:p.x+(p.x-mx)/l*.6,y:p.y+(p.y-my)/l*.6}};x.save();x.beginPath();[d0,d1,d2].map(out).forEach((p,k)=>k?x.lineTo(p.x,p.y):x.moveTo(p.x,p.y));x.closePath();x.clip();x.transform(a,b,c,e,d0.x-a*s0.x-c*s0.y,d0.y-b*s0.x-e*s0.y);x.drawImage(img,0,0);x.restore()}function mapOnto(x,img,pts,n=12){const at=squareTo(pts),w=img.width,h=img.height;for(let r=0;r<n;r++){for(let c=0;c<n;c++){const u0=c/n,u1=(c+1)/n,v0=r/n,v1=(r+1)/n;const S=(u,v)=>({x:u*w,y:v*h});triangle(x,img,[S(u0,v0),S(u1,v0),S(u1,v1)],[at(u0,v0),at(u1,v0),at(u1,v1)]);triangle(x,img,[S(u0,v0),S(u1,v1),S(u0,v1)],[at(u0,v0),at(u1,v1),at(u0,v1)])}}}async function drawShelf(x,w,top,bottom,u){const quads=ed.slots.map((s,i)=>quadOf(i)).sort((a,b)=>a.z-b.z);const all=quads.flatMap(q=>q.pts);const left=Math.min(...all.map(p=>p.x)),right=Math.max(...all.map(p=>p.x));const high=Math.min(...all.map(p=>p.y)),low=Math.max(...all.map(p=>p.y));const roomH=bottom-top,k=Math.min(w*.88/(right-left),roomH/((low-high)*1.08));const ox=(w-(right-left)*k)/2-left*k,oy=top+(roomH-(low-high)*1.08*k)/2-high*k;for(const q of quads){const pts=q.pts.map(p=>({x:ox+p.x*k,y:oy+p.y*k}));const coverW=Math.hypot(pts[1].x-pts[0].x,pts[1].y-pts[0].y)/ed.BOOK_WIDE;floorShadow(x,(pts[2].x+pts[3].x)/2-coverW*.05,Math.max(pts[2].y,pts[3].y)+coverW*.1,coverW*.5,.14*(1-q.fog));const tex=await ed.bookCanvas(q.i,Math.max(120,Math.min(900,Math.round(coverW*1.25))));mapOnto(x,tex,pts);if(q.fog){x.fillStyle=`rgba(255, 255, 255, ${q.fog})`;x.beginPath();pts.forEach((p,n)=>n?x.lineTo(p.x,p.y):x.moveTo(p.x,p.y));x.fill()}}}async function shelfImage({what=`front`,size=`post`,width=1080}={}){const[W0,H0]=SIZES[size]||SIZES.post;const u=width/W0,w=width,h=Math.round(H0*u);const cv=document.createElement(`canvas`);cv.width=w;cv.height=h;const x=cv.getContext(`2d`);if(document.fonts&&document.fonts.ready)await document.fonts.ready;x.fillStyle=PAPER;x.fillRect(0,0,w,h);const coverW=Math.min(657*u,(h-456*u)/1.36);const extra=Math.max(0,h-(coverW*1.36+456*u))/2;const top=118*u+extra,shadowY=top+coverW*1.36+88*u,wordY=shadowY+177*u;if(what===`shelf`)await drawShelf(x,w,Math.max(60*u,top-40*u),shadowY+40*u,u);else{const left=(w-coverW*ed.BOOK_WIDE)/2;floorShadow(x,left+coverW*.53,shadowY,coverW*.46,.2);x.save();x.translate(left,top);await ed.drawBook(x,ed.mod(Math.round(ed.near!==null?ed.near:ed.pos)),coverW);x.restore()}wordmark(x,w,wordY,u);return cv}};
;

// ---- pages/shelf-save-image.js ----
window.ShelfParts=window.ShelfParts||{};window.ShelfParts.addSaveImage=function addSaveImage(ed){"use strict";Object.assign(ed,{openSaveImage});const glyph=d=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${d}</svg>`;const CLOSE=glyph(`<path d="M6 6l12 12M18 6L6 18"/>`);const SIZE_NAMES={post:`Post 4:5`,story:`Story 9:16`,square:`Square`};const PREVIEW_W=236;const chip=(group,k,label,on)=>`<button type="button" class="save-chip" data-${group}="${k}" aria-pressed="${on}">${label}</button>`;const fileName=(what,b)=>`${what===`shelf`?`Documenting Fictions`:b.short}.png`;function openSaveImage(){const b=ed.BOOKS[ed.mod(Math.round(ed.pos))];let what=`front`,size=`post`,full=null,turn=0;const dim=document.createElement(`div`);dim.className=`sheet-dim`;dim.innerHTML=`<div class="sheet save-image" role="dialog" aria-modal="true" aria-label="Save as image">
      <div class="sheet-head"><h2>Save as image</h2><button type="button" class="ring-btn" data-close aria-label="Close"><span>${CLOSE}</span></button></div>
      <div class="save-preview"><img alt="" /></div>
      <span class="opt-label">What</span>
      <div class="save-chips">${chip(`what`,`front`,b.short,true)}${chip(`what`,`shelf`,`The whole shelf`,false)}</div>
      <span class="opt-label">Size</span>
      <div class="save-chips">${Object.entries(SIZE_NAMES).map(([k,n])=>chip(`size`,k,n,k===size)).join(``)}</div>
      <button type="button" class="sheet-btn primary save-go" data-save data-test-skip>Save and share</button></div>`;const sheet=dim.firstElementChild,img=sheet.querySelector(`.save-preview img`);document.body.appendChild(dim);requestAnimationFrame(()=>dim.classList.add(`in`));async function draw(){const mine=++turn;while(ed.busy)await ed.wait(60);sheet.querySelectorAll(`[data-what]`).forEach(c=>c.setAttribute(`aria-pressed`,String(c.dataset.what===what)));sheet.querySelectorAll(`[data-size]`).forEach(c=>c.setAttribute(`aria-pressed`,String(c.dataset.size===size)));const[w,h]=ed.IMAGE_SIZES[size];img.style.aspectRatio=`${w} / ${h}`;img.alt=what===`shelf`?`The whole shelf`:`${b.short}'s cover with its stickers`;const small=await ed.shelfImage({what,size,width:PREVIEW_W*2});if(mine!==turn)return;img.src=small.toDataURL(`image/png`);full=ed.shelfImage({what,size,width:w}).then(cv=>new Promise(ok=>cv.toBlob(ok,`image/png`))).then(blob=>blob?new File([blob],fileName(what,b),{type:`image/png`}):null)}const close=()=>{dim.classList.remove(`in`);setTimeout(()=>dim.remove(),220)};dim.addEventListener(`click`,async e=>{if(e.target===dim||e.target.closest(`[data-close]`)){close();return}const pick=e.target.closest(`[data-what], [data-size]`);if(pick){if(pick.dataset.what)what=pick.dataset.what;else size=pick.dataset.size;draw();return}if(e.target.closest(`[data-save]`)){try{const file=full&&await full;if(!file)throw new Error(`No picture`);if(await window.DFData.saveFile(file)===`downloaded`)ed.toast(`The picture is in your downloads`)}catch(err){console.error(err);ed.toast(`That couldn't be saved as a picture`)}}});draw();return dim}};
;

// ---- pages/shelf-waiting.js ----
window.ShelfParts=window.ShelfParts||{};window.ShelfParts.addWaiting=function addWaiting(ed){"use strict";Object.assign(ed,{paintWaiting,placeWaiting,openWaiting});const W=()=>window.DFWaiting;const C=()=>window.DFConnect;const CLOSE=`<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><line x1="6" y1="6" x2="18" y2="18"/><line x1="18" y1="6" x2="6" y2="18"/></svg>`;const CHEV=`<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><polyline points="9 5 16 12 9 19"/></svg>`;const BANG=`<svg class="bang" viewBox="0 0 24 56" aria-hidden="true"><rect x="6" y="0" width="12" height="34" fill="#313D45"/><circle cx="12" cy="47" r="8" fill="#FFD100"/></svg><span class="bang-floor" aria-hidden="true"></span>`;const esc=s=>String(s??``).replace(/[&<>"']/g,c=>({"&":`&amp;`,"<":`&lt;`,">":`&gt;`,'"':`&quot;`,"'":`&#39;`})[c]);const layer=document.createElement(`div`);layer.className=`waiting-marks`;ed.shelf.append(layer);const marks=ed.BOOKS.map((b,i)=>{const m=document.createElement(`button`);m.type=`button`;m.className=`waiting-mark`;m.hidden=true;m.dataset.i=i;m.style.setProperty(`--d`,`${-.8*i}s`);m.innerHTML=BANG;layer.append(m);return m});let waiting={};async function paintWaiting(){try{waiting=await W().waitingAll(ed.BOOKS.map(b=>b.id))}catch(e){return}ed.BOOKS.forEach((b,i)=>{const n=(waiting[b.id]||[]).length;marks[i].hidden=!n;if(n)marks[i].setAttribute(`aria-label`,W().waitingLabel(b.short,n))});placeWaiting()}const gliding=()=>ed.slots.some(s=>s.classList.contains(`reshaping`)||s.classList.contains(`turning`));function placeWaiting(){const away=ed.facing!==null||ed.near!==null||ed.closeT>0||ed.shelf.classList.contains(`away`)||gliding();layer.classList.toggle(`off`,away);if(away)return;marks.forEach((m,i)=>{if(m.hidden)return;const r=ed.slots[i].querySelector(`.front`).getBoundingClientRect();m.style.transform=`translate(${((r.left+r.right)/2-22).toFixed(1)}px, ${(r.top-70).toFixed(1)}px)`})}function rowHtml(r,k){const icon=r.kind===`handoff`?C().pairHtml(r.from,r.to):C().miniHtml(r.from);return`<button type="button" class="waiting-row" data-row="${k}">${icon}<span class="waiting-words"><span class="waiting-title">${esc(r.title)}</span>${r.line?`<span class="waiting-line">${esc(r.line)}</span>`:``}</span><span class="waiting-chev">${CHEV}</span></button>`}function openWaiting(i){const b=ed.BOOKS[i];const rows=waiting[b.id]||[];const nb=C().NOTEBOOKS[b.id];const dim=document.createElement(`div`);dim.className=`sheet-dim`;dim.innerHTML=`<div class="sheet waiting-sheet" role="dialog" aria-modal="true" aria-label="Waiting in ${esc(b.short)}">
      <div class="sheet-head"><span class="waiting-mini">${C().markSvg(b.id,24)}</span><h2>Waiting in ${esc(b.short)}</h2><button type="button" class="ring-btn" data-close aria-label="Close"><span>${CLOSE}</span></button></div>
      <div class="waiting-rows">${rows.map(rowHtml).join(``)}</div>
      <button type="button" class="sheet-btn primary waiting-open" data-open>Open ${esc(b.short)}</button>
    </div>`;const sheet=dim.firstElementChild;sheet.querySelector(`.waiting-mini`).style.background=nb.bg;sheet.querySelector(`.waiting-open`).style.background=nb.bg;sheet.querySelector(`.waiting-open`).style.setProperty(`--on`,nb.bg===`#FFD100`?`#313D45`:`#FFFFFF`);document.body.appendChild(dim);requestAnimationFrame(()=>dim.classList.add(`in`));const close=()=>{dim.classList.remove(`in`);setTimeout(()=>dim.remove(),220)};const go=params=>{dim.remove();ed.openBook(i,params)};dim.addEventListener(`click`,e=>{const row=e.target.closest(`[data-row]`);if(row)go(rows[Number(row.dataset.row)].params);else if(e.target.closest(`[data-open]`))go(null);else if(e.target===dim||e.target.closest(`[data-close]`))close()});return dim}layer.addEventListener(`click`,e=>{const m=e.target.closest(`.waiting-mark`);if(m&&!ed.busy)openWaiting(Number(m.dataset.i))});window.addEventListener(`load`,paintWaiting);window.addEventListener(`resize`,placeWaiting);window.addEventListener(`pageshow`,e=>{if(e.persisted)paintWaiting()});document.addEventListener(`visibilitychange`,()=>{if(!document.hidden)paintWaiting()})};
;

// ---- components/thing-rows.js ----
window.ShelfParts=window.ShelfParts||{};window.ShelfParts.thingRows=(function(){"use strict";const D=()=>window.DFData;const C=()=>window.DFConnect;const BACK=`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M15 5l-7 7 7 7"/></svg>`;const CHEV=`<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><polyline points="9 5 16 12 9 19"/></svg>`;const CAMERA=`<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round" aria-hidden="true"><path d="M4 8h3l2-2.5h6L17 8h3v11H4z"/><circle cx="12" cy="13.5" r="3.5"/></svg>`;const SOMEONE=`<svg viewBox="0 0 24 24" width="40" height="40" fill="currentColor" aria-hidden="true"><circle cx="12" cy="8.5" r="4"/><path d="M4.5 21a7.5 7.5 0 0 1 15 0z"/></svg>`;const esc=s=>String(s??``).replace(/[&<>"']/g,c=>({"&":`&amp;`,"<":`&lt;`,">":`&gt;`,'"':`&quot;`,"'":`&#39;`})[c]);const firstName=name=>String(name||``).trim().split(/\s+/)[0]||`them`;function picture(page,c){const url=c?D().pictureUrl(c):``;if(url)page.urls.push(url);return url}const profile=p=>p.instagram?{url:`https://www.instagram.com/${encodeURIComponent(p.instagram)}/`,handle:p.instagram}:p.tiktok?{url:`https://www.tiktok.com/@${encodeURIComponent(p.tiktok)}`,handle:p.tiktok}:null;function partHtml(app,title,count,body){const nb=C().NOTEBOOKS[app];return`<section class="person-part" data-app="${app}"><div class="person-part-head"><span class="person-mark" style="background:${nb.bg}">${C().markSvg(app,20)}</span>
      <h2>${esc(title)}${count?` <span>${count}</span>`:``}</h2></div>${body}</section>`}const rowHtml=(t,thumb)=>`<button type="button" class="person-row" data-thing="${esc(t.key)}">${thumb}<span class="person-words"><span class="person-title">${esc(t.title)}</span>${t.line?`<span class="person-line">${esc(t.line)}</span>`:``}</span><span class="person-chev">${CHEV}</span></button>`;const shootThumb=(page,t)=>{const u=picture(page,t.covers[0]);return`<span class="person-shoot">${u?`<img src="${u}" alt="">`:CAMERA}</span>`};const boardThumb=(page,t)=>`<span class="person-board">${[0,1,2].map(k=>{const u=picture(page,t.covers[k]);return`<span>${u?`<img src="${u}" alt="">`:``}</span>`}).join(``)}</span>`;function nextHtml(t,named=false){const next=t.more.next||{};const when=next.line||t.line;const icon=`<span class="person-kind" style="background:${esc(next.bg||`#0A4FD6`)}">${next.icon||``}</span>`;return rowHtml({...t,title:next.title||t.title,line:named?[t.title,when].filter(Boolean).join(` · `):when},icon)}const postHtml=(page,t)=>{const u=picture(page,t.covers[0]);return`<button type="button" class="person-post" data-thing="${esc(t.key)}" aria-label="${esc(t.title)}">${u?`<img src="${u}" alt="">`:`<span>${esc(t.title)}</span>`}</button>`};function openThing(ed,t){document.querySelectorAll(`.connect-page`).forEach(p=>{(p.urls||[]).forEach(u=>URL.revokeObjectURL(u));p.remove()});ed.openBook(ed.BOOKS.findIndex(b=>b.id===t.app),t.params)}return{BACK,CHEV,CAMERA,SOMEONE,esc,firstName,picture,profile,partHtml,rowHtml,shootThumb,boardThumb,nextHtml,postHtml,openThing}})();
